        <div id="m-turn-cfg"><label for="turn-url">Relay URL</label><input id="turn-url" data-turn="turnUrl" spellcheck="false" autocomplete="off" placeholder="turns:relay.example.com:443?transport=tcp"/><label for="turn-user">Username</label><input id="turn-user" data-turn="turnUser" spellcheck="false" autocomplete="off"/><label for="turn-pass">Password</label><input id="turn-pass" data-turn="turnPass" type="password" autocomplete="off"/></div>
